import ipaddress
import urllib.parse
import urllib.request

def validate_and_open_webhook(url: str, opener=urllib.request.urlopen) -> str:
    parsed_url = urllib.parse.urlparse(url)
    if not parsed_url.scheme or not parsed_url.netloc:
        raise ValueError("Invalid URL format")

    allowed_schemes = {'http', 'https'}
    if parsed_url.scheme not in allowed_schemes:
        raise ValueError(f"Unsupported URL scheme: {parsed_url.scheme}")

    try:
        ip_address = ipaddress.ip_address(parsed_url.hostname)
        if ip_address.is_private or ip_address.is_loopback or ip_address.is_link_local:
            raise ValueError(f"Prohibited IP address: {ip_address}")
    except ValueError:
        # If not an IP address, assume it's a domain and proceed
        pass

    with opener(url, timeout=3) as resp:
        return resp.read().decode("utf-8")

